    """Density in g/cm^3 of a cubic crystal of one element.
    structure: "sc", "bcc", "fcc" or "diamond"; a_nm: lattice parameter in nm;
    molar_mass: in g/mol."""
    NA = 6.02214076e23
    return 0.0

exercises.reference:
def density(structure, a_nm, molar_mass):
    NA = 6.02214076e23
    n = {"sc": 1, "bcc": 2, "fcc": 4, "diamond": 8}[structure]
    return n * molar_mass / (NA * (a_nm * 1e-7) ** 3)

