from fractions import Fraction

def miller_indices(intercepts):
    """Miller indices (h, k, l) of a plane that cuts the x, y and z axes at the given
    intercepts, in units of the lattice parameters. None means the plane is parallel to
    that axis (it never cuts it). Return the smallest whole numbers, e.g. (1, 0, 0)."""
    return (0, 0, 0)

exercises.reference:
from fractions import Fraction
from math import gcd

def miller_indices(intercepts):
    recips = [Fraction(0) if x is None else 1 / Fraction(x).limit_denominator(1000) for x in intercepts]
    lcm = 1
    for r in recips:
        lcm = lcm * r.denominator // gcd(lcm, r.denominator)
    ints = [int(r * lcm) for r in recips]
    g = 0
    for i in ints:
        g = gcd(g, abs(i))
    return tuple(i // g for i in ints)
